// Verbatim sentences from the Captain's published chapters. SERVER-ONLY: never import from client code.
import type { KeyFact } from "../chapter-key-facts";

export const OPENER_FACTS: Record<string, KeyFact[]> = JSON.parse("{\"air-navigation/nav-13\":[{\"term\":\"The Poles\",\"fact\":\"The Poles are the extremities of the Earth's spin axis.\"},{\"term\":\"Reciprocal Directions\",\"fact\":\"The reciprocal of a direction is direction ± 180°.\"},{\"term\":\"Great Circle\",\"fact\":\"A Great Circle is a circle on the Earth's surface whose centre and radius are those of the Earth itself.\"},{\"term\":\"Meridians\",\"fact\":\"Meridians are semi-Great Circles joining North and South poles.\"},{\"term\":\"The Prime (Greenwich) Meridian\",\"fact\":\"The meridian through Greenwich is the Prime Meridian — the datum for Longitude (equivalent to the Y-axis).\"}],\"air-navigation/nav-15\":[{\"term\":\"Maximum Variation = 180°\",\"fact\":\"The maximum possible value of variation is 180°.\"},{\"term\":\"The Real Variation Map — Isogonals & Agonic Lines\",\"fact\":\"The real magnetic field is more complex than the idealised model — it resembles a bent bar magnet.\"},{\"term\":\"Changes in Variation Over Time\",\"fact\":\"Variation at any point changes with time because the Magnetic Poles are moving.\"},{\"term\":\"Magnetic Dip — Angle, H and Z Components\",\"fact\":\"The Earth's magnetic field acts along a total force vector T, which is directed into the Earth at an angle to the horizontal.\"},{\"term\":\"The 6 µT Threshold & Compass Reliability\",\"fact\":\"The accepted threshold below which H is too weak to reliably drive a magnetic compass is 6 microteslas (µT).\"}],\"air-navigation/nav-17\":[{\"term\":\"Track Error Angle vs Drift — Critical Distinction\",\"fact\":\"The track you intended to fly is the Planned Track.\"},{\"term\":\"Common Exam Trap — TEA is NOT Drift\",\"fact\":\"Drift is the angle between Heading and Track (either planned track or TMG).\"},{\"term\":\"ℹ Not EASA ATPL Examined\",\"fact\":\"The practical map-marking techniques in this section are not examined in the EASA ATPL.\"},{\"term\":\"New Track Reference — The Preferred Method\",\"fact\":\"New Track Reference combines the single-calculation method with a systematic re-correction procedure whenever a new fix is obtained.\"}],\"air-navigation/nav-19\":[{\"term\":\"Spot Heights and Mountain Triangles\",\"fact\":\"A spot height is a precise, surveyed elevation of a specific point, shown as a black dot with a number alongside.\"},{\"term\":\"Map Reading\",\"fact\":\"Map reading is defined as visualising the physical features of the ground as represented on the map by symbols, and forming a mental picture of the ground by relating those features to one another.\"},{\"term\":\"Map-to-Ground (Confident Technique)\",\"fact\":\"Used when you are confident of your approximate position.\"},{\"term\":\"Motorways and Major Roads\",\"fact\":\"A large motorway interchange (cloverleaf or trumpet junction) is arguably the finest inland checkpoint: unique shape, visible at high altitude, shown clearly on charts and rarely changed.\"},{\"term\":\"Rivers and Coastlines\",\"fact\":\"River meanders (S-bends) are highly distinctive from the air.\"}],\"air-navigation/nav-20\":[{\"term\":\"Meridians and Convergency\",\"fact\":\"Meridians are great semi-circles that join the geographic North and South Poles.\"},{\"term\":\"When the Two Points are at Different Latitudes\",\"fact\":\"In practice, most great circle routes go from one latitude to another — the two endpoints are not on the same parallel.\"},{\"term\":\"Great Circle Track and Convergency\",\"fact\":\"The amount by which a great circle track changes direction between two meridians is exactly equal to the convergency between those two meridians.\"},{\"term\":\"VOR Bearings\",\"fact\":\"A VOR radial is a bearing measured from the station (QDR).\"},{\"term\":\"NDB/ADF Bearings\",\"fact\":\"An NDB bearing is measured at the aircraft.\"}],\"air-navigation/nav-21\":[{\"term\":\"Definition of Departure\",\"fact\":\"Departure is the distance between two meridians measured along a specified parallel of latitude, expressed in nautical miles.\"},{\"term\":\"Why Departure Varies with Latitude\",\"fact\":\"The parallels of latitude are great circles.\"},{\"term\":\"Inspection of Answers — A Time-Saving Technique\",\"fact\":\"For MCQ examinations, it is often not necessary to calculate the exact answer.\"}],\"air-navigation/nav-23\":[{\"term\":\"Perspective vs Non-perspective Charts\",\"fact\":\"Perspective (geometric) projections are produced directly from an optical projection — the shadow method described above.\"},{\"term\":\"The Reduced Earth (RE)\",\"fact\":\"The Reduced Earth is the scale model of the Earth on which a projection is based.\"},{\"term\":\"Azimuthal / Plane Projections\",\"fact\":\"An azimuthal projection is produced by placing a flat sheet of paper against a single point on the Reduced Earth.\"}],\"air-navigation/nav-25\":[{\"term\":\"Scale on the Simple Conic Projection\",\"fact\":\"On the simple conic, scale is correct only at the parallel of tangency.\"},{\"term\":\"Lambert's Modification — Bringing the Cone Inside\",\"fact\":\"Lambert's key insight: by pushing the cone inside the Reduced Earth (rather than leaving it touching the outside), the single line of correct scale at the parallel of tangency is replaced by two parallels of correct scale — the standard parallels.\"},{\"term\":\"Scale\",\"fact\":\"Scale is least at the Parallel of Origin (between the two standard parallels).\"},{\"term\":\"Parallel of Origin\",\"fact\":\"The Parallel of Origin is the mathematical basis of the projection.\"},{\"term\":\"The Key Rule for Great Circles on Lambert Charts\",\"fact\":\"A Great Circle is a straight line only at the Parallel of Origin.\"}],\"air-navigation/nav-26\":[{\"term\":\"Scale Expansion\",\"fact\":\"Scale is correct at the Pole (the point of tangency).\"},{\"term\":\"Great Circles\",\"fact\":\"Great circles are also curves concave to the Pole, but with less curvature than Rhumb Lines in the same hemisphere.\"}],\"air-navigation/nav-27\":[{\"term\":\"Kepler's Third Law — Period vs. Size\",\"fact\":\"The square of the orbital period of a planet is proportional to the cube of the semi-major axis of its orbit.\"},{\"term\":\"The Seasons\",\"fact\":\"The seasons are not caused by the Earth's distance from the Sun (the distance difference only changes solar heat by ~3%).\"},{\"term\":\"Declination\",\"fact\":\"The angle the Sun is above or below the Equator is called Declination.\"},{\"term\":\"Measurement of Days and Years\",\"fact\":\"A 'day' is the time taken for the Earth to rotate once about its axis, measured against a celestial body.\"},{\"term\":\"The Equation of Time\",\"fact\":\"The difference between apparent noon (when the real Sun transits the meridian) and mean noon (1200 LMT) is called the Equation of Time.\"}],\"air-navigation/nav-28\":[{\"term\":\"Local Mean Time (LMT)\",\"fact\":\"Local Mean Time is based on the position of the mean Sun relative to the observer's own meridian.\"},{\"term\":\"Co-ordinated Universal Time (UTC)\",\"fact\":\"UTC is a single, worldwide time standard based on the mean Sun as seen from the Greenwich Meridian (0°).\"},{\"term\":\"Standard Time (ST)\",\"fact\":\"Standard Time is the legal time kept by a country, established by government legislation.\"}],\"air-navigation/nav-29\":[{\"term\":\"Sunrise and Sunset\",\"fact\":\"Sunrise LMT and Sunset LMT are the same at a given latitude on a given date, regardless of longitude.\"},{\"term\":\"Twilight\",\"fact\":\"Twilight is the period before sunrise and after sunset when the Sun is below the sensible horizon but still illuminates the sky.\"},{\"term\":\"Twilight at the Equator\",\"fact\":\"Despite popular belief, it is not immediately dark after sunset at the Equator.\"},{\"term\":\"Minimum Duration of Civil Twilight\",\"fact\":\"Between 60°N and 60°S, the minimum duration of civil twilight is 21 minutes.\"},{\"term\":\"Effect of Altitude on Sunrise/Sunset\",\"fact\":\"Sunrise is earlier — you can see the Sun before it rises above the sea-level horizon.\"}],\"air-navigation/nav-30\":[{\"term\":\"The Magnetic Compass\",\"fact\":\"A compass is an instrument designed to indicate direction relative to a known datum.\"},{\"term\":\"The Vertical Card Compass (B-type / E-type)\",\"fact\":\"The vertical card compass consists of a circular compass card attached directly to the magnet assembly, suspended in liquid within a compass bowl.\"},{\"term\":\"The Grid Ring Compass (P-type)\",\"fact\":\"The grid ring compass is found on older aircraft.\"},{\"term\":\"Achieving Horizontality — Pendulous Suspension\",\"fact\":\"To achieve horizontality, the magnet assembly is pendulously suspended — the centre of gravity is placed below the supporting pivot.\"},{\"term\":\"Deviation\",\"fact\":\"Deviation is caused by iron/steel components, electrical currents and other magnetic influences within the aircraft distorting the local Earth's field at the compass location.\"}],\"air-navigation/nav-31\":[{\"term\":\"Deviation\",\"fact\":\"Deviation is the angle between the local magnetic meridian and the direction in which the compass magnets are actually pointing, caused by the aircraft's own magnetic influence on the compass.\"},{\"term\":\"Hard Iron Magnetism\",\"fact\":\"Hard iron is mainly resolved by Coefficients B and C in the compass swing analysis.\"},{\"term\":\"Soft Iron Magnetism\",\"fact\":\"Soft iron components are those that are temporarily magnetized by the Earth's field.\"},{\"term\":\"Compass Swing\",\"fact\":\"A compass swing is the systematic process of measuring and then minimizing deviation on all headings, followed by recording the residual deviation.\"},{\"term\":\"Compass Swing Conditions\",\"fact\":\"The reference direction is established using a datum compass or surveyed alignment marks.\"}],\"air-navigation/nav-32\":[{\"term\":\"Triangle of Velocities — Wind Component Geometry\",\"fact\":\"A common misconception is that a wind at right angles to heading or track produces zero headwind/tailwind component.\"}],\"air-navigation/nav-1\":[{\"term\":\"Reciprocal Directions\",\"fact\":\"The reciprocal of any bearing is the direction exactly 180° opposite.\"},{\"term\":\"Parallels of Latitude\",\"fact\":\"Small circles whose planes are parallel to the Equator.\"},{\"term\":\"Reversal at 180°E (Anti-Meridian)\",\"fact\":\"At the Greenwich Meridian: Eastern longitudes are to your East.\"}],\"meteorology/met-1\":[{\"term\":\"Definition — Atmosphere\",\"fact\":\"The atmosphere of the earth is an envelope of homogeneous mixture of gases, called Air.\"},{\"term\":\"Supplementary Oxygen Required\",\"fact\":\"Due to rapid reduction of gases with height, supplementary oxygen is needed above 10,000 ft.\"},{\"term\":\"Global Warming Warning\",\"fact\":\"Excessive amount of greenhouse gases is causing Global Warming, which is a serious threat to our life and needs to be limited.\"}],\"meteorology/met-2\":[{\"term\":\"Static and Dynamic Pressure\",\"fact\":\"Pressure is the force per unit area exerted by molecules of air in random motion, acting uniformly in all directions.\"},{\"term\":\"Pressure as Weight of Air Above\",\"fact\":\"The atmospheric pressure at any level is the weight of the column of air of unit cross-section extending vertically to the top of the atmosphere.\"},{\"term\":\"Semi-Diurnal Variation of Pressure\",\"fact\":\"Variations are: very small at the Poles and about 3–5 hPa at the Equator.\"},{\"term\":\"Altimeter Correction (Alticor / D Value)\",\"fact\":\"The correction applied to indicated altitude to obtain true altitude is called Altimeter Correction (also called Alticor).\"},{\"term\":\"Contours\",\"fact\":\"In Contour Charts, contours are drawn at an interval of 40 gpm (geopotential metre) in 700 hPa and 500 hPa level charts; and at 80 gpm in 300 hPa and 200 hPa level charts.\"}],\"meteorology/met-3\":[{\"term\":\"Heat and Temperature\",\"fact\":\"Heat is the sum total of the Kinetic Energy (KE) of all molecules and atoms of a substance.\"},{\"term\":\"Specific Heat\",\"fact\":\"Specific Heat is the heat required to raise the temperature of unit mass of a substance by 1°C.\"},{\"term\":\"Latent Heat\",\"fact\":\"Latent Heat is defined as the \\\"amount of heat absorbed or released during change of phase from/to solid/liquid/vapour\\\".\"},{\"term\":\"Evaporation, Condensation and Latent Heat\",\"fact\":\"Once boiling has begun, the temperature remains constant — heat supplied at this stage is latent.\"},{\"term\":\"Methods of Heat Transfer\",\"fact\":\"Heat is transferred by Conduction, Convection, Radiation, and other methods.\"}],\"meteorology/met-4\":[{\"term\":\"Factors Affecting Air Density\",\"fact\":\"Air density is affected by three factors: Altitude, Temperature, and Humidity.\"},{\"term\":\"Variations in Surface Density\",\"fact\":\"At a given pressure, density is inversely proportional to absolute temperature.\"},{\"term\":\"Latitudinal Variation of Density\",\"fact\":\"Density of air at sea level is lowest near the equator and greatest at the poles.\"}],\"meteorology/met-5\":[{\"term\":\"Relative Humidity (RH)\",\"fact\":\"Relative Humidity is defined as the ratio, in percentage, of the actual water vapour in the air to the maximum it can contain at the same temperature and pressure.\"},{\"term\":\"Temperature Relationships — Saturated vs Unsaturated Air\",\"fact\":\"In normal (unsaturated) air, air temperature is highest, wet bulb is intermediate, and dew point is lowest.\"}],\"meteorology/met-6\":[{\"term\":\"Wind Measurement & Cross Wind\",\"fact\":\"Wind is the horizontal movement of air from high pressure to low pressure.\"},{\"term\":\"Cross Wind\",\"fact\":\"Runways are oriented along the most prevailing wind directions of a locality based on climatological records.\"},{\"term\":\"Inertial Wind\",\"fact\":\"The inertial flow is Anticyclonic in BOTH hemispheres.\"},{\"term\":\"Thermal Wind\",\"fact\":\"The thermal wind in a layer is defined as that wind which must be added vectorially to the geostrophic wind at the lower level in order to obtain the geostrophic wind at the upper level.\"},{\"term\":\"Wind and Contours\",\"fact\":\"Lines joining equal heights on a constant pressure level are called Contours.\"}],\"meteorology/met-7\":[{\"term\":\"Definition of Visibility\",\"fact\":\"Visibility on the ground and from the air are of great importance to a pilot for landing and take-off.\"}],\"meteorology/met-8\":[{\"term\":\"Causes of Vertical Motion\",\"fact\":\"Vertical motion in the atmosphere — either upward (ascent) or downward (subsidence) — is driven by several mechanisms.\"},{\"term\":\"Cloud Amount in Imaginary Oktas\",\"fact\":\"For expressing cloud amount, the sky is divided into eight imaginary parts.\"}],\"meteorology/met-9\":[{\"term\":\"Inversion Layer\",\"fact\":\"An atmospheric layer in which there is an inversion of temperature.\"},{\"term\":\"Normand Theorem and Normand Point\",\"fact\":\"The first Normand Point (from the surface) is the First Normand Point.\"}],\"meteorology/met-10\":[{\"term\":\"Mirage\",\"fact\":\"Mirages are due to curving of light rays passing through layers of air in which refractive index changes considerably with height due to density differences.\"},{\"term\":\"Twilight Colours\",\"fact\":\"Various colours in the sky are produced at sunset and at sunrise by refraction, scattering or selective absorption of light rays from the sun.\"}],\"meteorology/met-11\":[{\"term\":\"Snow and Sleet\",\"fact\":\"Snowfall is usually in the form of flakes = mixtures of various shapes of minute ice-crystals.\"}],\"meteorology/met-12\":[{\"term\":\"Airframe Icing in Relation to Cloud Forms\",\"fact\":\"Ice accretion is dependent primarily on the size and number of drops in a cloud.\"},{\"term\":\"Carburetor Icing\",\"fact\":\"Below −10°C: this type of icing is negligible unless liquid water is present.\"}],\"meteorology/met-13\":[{\"term\":\"Structure of Severe TS\",\"fact\":\"Severe TS are tilted due to vertical WS.\"}],\"meteorology/met-14\":[{\"term\":\"Air Masses — Definition & Classification\",\"fact\":\"A large body of air covering an area of thousands of square kilometres in which the horizontal and vertical distribution of temperature (density) and moisture are nearly uniform.\"},{\"term\":\"Fronts — Definition & Terminology\",\"fact\":\"The sloping surface along which the two air masses exist and meet; the place where this frontal surface meets the ground is the front.\"},{\"term\":\"Fronts in India\",\"fact\":\"India is not affected by fronts, except in extreme NW India.\"}],\"meteorology/met-15\":[{\"term\":\"Temperature Distribution & Wind Shear\",\"fact\":\"STJ is caused by a concentration of horizontal temperature gradient below the jet and reversal above it.\"},{\"term\":\"Cause\",\"fact\":\"Jetstream is caused by the large horizontal temperature gradient.\"},{\"term\":\"Clear Air Turbulence (CAT)\",\"fact\":\"Looking downstream: CAT is to the LEFT in the Northern Hemisphere; to the right in Southern Hemisphere.\"}],\"meteorology/met-16\":[{\"term\":\"Definition & Necessary Conditions\",\"fact\":\"Clear Air Turbulence (CAT) is the bumpiness experienced by aircraft at high altitudes in cloud-free conditions, excluding Ci clouds.\"},{\"term\":\"Causes & Sources of CAT\",\"fact\":\"Even when the lapse rate is small or negative, a marked decrease of wind speed with height may give rise to temporary zones of CAT.\"},{\"term\":\"Sources of CAT\",\"fact\":\"CAT occurs when strong winds encounter the tops of thunderstorm clouds, resulting in waves that extend well downstream from the cloud.\"}],\"meteorology/met-17\":[{\"term\":\"Vertical Currents\",\"fact\":\"An aircraft flying parallel to a ridge, if caught in the down current, would suffer constant loss of height till the whole length of the ridge is traversed.\"},{\"term\":\"Turbulence\",\"fact\":\"Wave cloud outlines that are not smooth but have ragged appearance = indication of turbulence.\"}],\"meteorology/met-18\":[{\"term\":\"Frequency of Cyclones\",\"fact\":\"Frequency in Bay of Bengal and Arabian Sea is almost nil in February and March.\"}],\"meteorology/met-19\":[{\"term\":\"Upper Winds — SW Monsoon\",\"fact\":\"Up to about 10,000 ft winds are W–SWly to the S of MT and to the N.\"},{\"term\":\"Surface Temperature & Winds\",\"fact\":\"Temperatures are nearly uniform, 18°C, over the country.\"}],\"meteorology/met-20\":[{\"term\":\"Three Cell Model of General Circulation\",\"fact\":\"The Three Cell Model describes the average circulation of the atmosphere and the atmospheric energy transport.\"},{\"term\":\"Rossby Waves (Planetary Waves)\",\"fact\":\"The meandering jet streams are Rossby waves.\"}],\"meteorology/met-21\":[{\"term\":\"SIGMET\",\"fact\":\"SIGMETs are passed to FIC/ACC for further communication to aircraft in flight.\"},{\"term\":\"Wind Shear Warning\",\"fact\":\"Microburst reported by pilots is also included in the warning.\"}],\"meteorology/met-22\":[{\"term\":\"Doppler Weather Radar (DWR)\",\"fact\":\"DWR is a state-of-art Radar that works on the principle of Doppler Effect and measures change of frequency of the return signal to determine if targets are moving towards or away from the radar station.\"},{\"term\":\"Stratiform Cloud Echoes\",\"fact\":\"Echoes from Stratiform clouds and steady rainfall are diffused and ill-defined; generally of uniform intensity.\"}],\"meteorology/met-25\":[{\"term\":\"METAR and SPECI — Introduction\",\"fact\":\"METAR is issued at half hourly or hourly intervals.\"},{\"term\":\"RVR — Runway Visual Range\",\"fact\":\"RVR observations are made when visibility or RVR < 1500 m.\"},{\"term\":\"SPECIAL Report (India-specific)\",\"fact\":\"In addition to SPECI, a SPECIAL Report (in abbreviated plain language) is issued for Height of Base of Clouds and Visibility in India.\"},{\"term\":\"TREND Forecast (Landing Forecast)\",\"fact\":\"TREND is appended to a METAR or SPECI and is valid for TWO hours.\"}],\"meteorology/met-27\":[{\"term\":\"Radar Report (RAREP) — Introduction & Code\",\"fact\":\"RAREP is normally reported only at synoptic hours.\"},{\"term\":\"SIGMET Message\",\"fact\":\"SIGMET for subsonic aircraft is identified as SIGMET SST.\"},{\"term\":\"Satellite Bulletin\",\"fact\":\"Satellite imageries are analysed and supplied as Bulletins in abbreviated form.\"}],\"meteorology/met-28\":[{\"term\":\"Pre-Flight Briefing\",\"fact\":\"Pre-flight briefing is the provision of meteorological information to the flight crew before departure, covering weather conditions relevant to the planned route and aerodromes.\"},{\"term\":\"In-Flight Information Provided to Operators / Crew\",\"fact\":\"For in-flight planning: Information is supplied to Operators by the Met Office.\"}],\"air-regulations/ar-2\":[{\"term\":\"How the Marks Are Affixed\",\"fact\":\"The nationality marks allotted to India by ITU are AT to AW (not VT or VU).\"},{\"term\":\"Use of State Marks\",\"fact\":\"Are not capable of confusion with, the nationality and registration marks of the aircraft.\"},{\"term\":\"IFSC, IFSCA & GIFT City\",\"fact\":\"GIFT City is in Gandhinagar, Gujarat, under the SEZ Act, 2005.\"}],\"air-regulations/ar-4\":[{\"term\":\"Air Traffic Control Service (ATC)\",\"fact\":\"Provided by: Area Control Centre (ACC), or by the Approach Control unit where no ACC is established.\"},{\"term\":\"Designation of Airspace Portions\",\"fact\":\"Portions where Flight Information Service and Alerting Service will be provided are designated as Flight Information Regions.\"},{\"term\":\"Procedures in Class C Airspace (India-Specific)\",\"fact\":\"Airports with runway handling capacity of >20 aircraft/hour AND equipped with primary and secondary radars are designated Class C.\"},{\"term\":\"Air Traffic Flow Management (ATFM)\",\"fact\":\"ATFM is primarily meant to balance demand against capacity to achieve optimum utilisation of major resources — Airport, Airspace, and Aircraft — at every Indian airport where there is a capacity constraint.\"},{\"term\":\"Scope of FIS – Information Included\",\"fact\":\"SIGMET and AIRMET information ( Note: AIRMET is NOT provided in India).\"}],\"air-regulations/ar-5\":[{\"term\":\"Longitudinal Separation — Distance Based (DME / GNSS)\",\"fact\":\"Direct controller-pilot VHF voice communication shall be maintained while this separation is used.\"},{\"term\":\"Essential Traffic Information\",\"fact\":\"Essential traffic is that controlled traffic to which the provision of separation by ATC is applicable, but which, in relation to a particular controlled flight, is not, or will not be, separated from other controlled traffic by the appropriate separation minimum.\"}],\"air-regulations/ar-6\":[{\"term\":\"Reduction in Separation Minima Near Aerodromes\",\"fact\":\"Adequate separation can be provided by the aerodrome controller when each aircraft is continuously visible to this controller.\"},{\"term\":\"Expected Approach Time (EAT) & Onward Clearance Time\",\"fact\":\"An Expected Approach Time (EAT) is the time at which ATC expects that an arriving aircraft, following a delay, will be cleared to commence its approach from the holding fix.\"}],\"air-regulations/ar-7\":[{\"term\":\"· Use of Runway-Holding Positions\",\"fact\":\"Aircraft shall NOT be permitted to line up and hold on the approach end of a runway-in-use whenever another aircraft is effecting a landing — until the landing aircraft has passed the point of intended holding.\"},{\"term\":\"· Control of Traffic in the Traffic Circuit\",\"fact\":\"The clearance to enter the traffic circuit should be issued to an aircraft whenever it is desired that the aircraft approach the landing area in accordance with current traffic circuits but traffic conditions do not yet allow a landing clearance to be issued.\"},{\"term\":\"· Wind Shear Advisories\",\"fact\":\"Wind shear is a sustained change in the wind velocity along the aircraft flight path, which occurs significantly faster than the aircraft can accelerate or decelerate.\"}],\"air-regulations/ar-8\":[{\"term\":\"ADS-B — Automatic Dependent Surveillance – Broadcast\",\"fact\":\"ADS-B, like PSR and SSR, is an ATS surveillance system.\"},{\"term\":\"MLAT — Multilateration Applications\",\"fact\":\"Multilateration (MLAT) is a technology to accurately locate aircraft using Time Difference of Arrival (TDOA).\"},{\"term\":\"Radar Flight Information Service\",\"fact\":\"Radar separation may be provided between two radar-identified aircraft even when only one of the aircraft is in direct communication with the radar unit.\"},{\"term\":\"Separation Minima\",\"fact\":\"The separation minima specified shall only be applied between identified aircraft when there is reasonable assurance that identification will be maintained.\"},{\"term\":\"India — Separation Minima\",\"fact\":\"For separation minima based on ATS surveillance systems in India, please refer to Chapter Six of the Air Regulations text.\"}],\"air-regulations/ar-9\":[{\"term\":\"Trigger NOTAM\",\"fact\":\"The intent of a Trigger NOTAM is to serve as a reminder in the pre-flight information bulletin (PIB) for the forthcoming operationally significant change in the AIP (via AIP Supplement), if applicable.\"},{\"term\":\"Runway Condition Code (RWYCC)\",\"fact\":\"The Runway Condition Code (RWYCC) is used for reporting assessed runway information.\"},{\"term\":\"ASHTAM\",\"fact\":\"Information concerning an operationally significant change in volcanic activity, a volcanic eruption and/or volcanic ash cloud shall, when reported by means of an ASHTAM, contain the information in the order shown in the ASHTAM Format.\"},{\"term\":\"NOTAM Distribution\",\"fact\":\"The originator shall select the NOTAM that are to be given international distribution.\"},{\"term\":\"Provision of Information in Paper Copy Form\",\"fact\":\"For major changes where advance notice is desirable and practicable — information in paper copy should be distributed by the AIS unit.\"}],\"air-regulations/ar-10\":[{\"term\":\"SAR Services — International Obligations\",\"fact\":\"Contracting States shall, individually or in cooperation with other States, arrange for the establishment and prompt provision of search and rescue services within their territories to ensure that assistance is rendered to persons in distress.\"},{\"term\":\"Search & Rescue Regions (SRR)\",\"fact\":\"An area of defined dimensions associated with a Rescue Coordination Centre within which SAR services are provided.\"},{\"term\":\"Air-to-Ground Signals\",\"fact\":\"A clear, visible acknowledgement that ground signals are understood.\"}],\"air-regulations/ar-11\":[{\"term\":\"Aiming Point Marking\",\"fact\":\"An aiming point marking shall be provided at each approach end of a paved instrument runway where the code number is 2, 3 or 4.\"},{\"term\":\"Touchdown Zone (TDZ) Marking\",\"fact\":\"A TDZ marking shall be provided in the touchdown zone of a paved precision approach runway where the code number is 2, 3 or 4.\"},{\"term\":\"Runway Side Stripe Marking\",\"fact\":\"Shall be provided between the thresholds of a paved runway where there is a lack of contrast between the runway edges and the shoulders or surrounding terrain.\"},{\"term\":\"Taxiway Centre Line Marking\",\"fact\":\"Taxiway centre line marking shall be provided on a paved taxiway, de-icing/anti-icing facility and apron where the code number is 3 or 4, providing continuous guidance between the runway centre line and aircraft stands.\"},{\"term\":\"Apron Safety Lines\",\"fact\":\"Apron safety lines shall be of red colour in India (contrasting with aircraft stand markings which are yellow).\"}],\"air-regulations/ar-12\":[{\"term\":\"Instrument Departure Procedure — Design\",\"fact\":\"Design of an IDP is dictated by the terrain surrounding the aerodrome.\"},{\"term\":\"Procedure Design Gradient (PDG)\",\"fact\":\"The PDG is an aid to the procedures designer, who adjusts the route to minimise the PDG consistent with other constraints.\"},{\"term\":\"Radar Vectors during Departure\",\"fact\":\"The departure route is non-critical with respect to obstacle clearance.\"},{\"term\":\"Standard Instrument Departures (SIDs)\",\"fact\":\"A straight departure is one in which the initial departure track is within 15° of the alignment of the runway centre line.\"},{\"term\":\"Categories of Aeroplanes & Speed Table\",\"fact\":\"Five categories based on the indicated airspeed at threshold (V at) which equals the stall speed V SO × 1.3 or stall speed V S1g × 1.23 (whichever is higher) in landing configuration at maximum certificated landing mass.\"}],\"air-regulations/ar-13\":[{\"term\":\"Part 1: The Aircraft Act, 1934 Central Legislation\",\"fact\":\"The Aircraft Act, 1934 is an Act of Parliament for the control of manufacture, possession, use, operation, sale, import and export of aircraft in India.\"}],\"air-regulations/ar-14\":[{\"term\":\"Role of the Training Manuals\",\"fact\":\"Related ICAO training manuals guide States on the scope and depth of training curricula, so that the confidence in safe air navigation intended by the Convention and Annex 1 is maintained.\"},{\"term\":\"Conditions Under Which a Licence is Deemed Invalid\",\"fact\":\"The holder shall not exercise the privileges of his licence during any period when he is aware that his physical condition has deteriorated below the standard required for that category of licence.\"},{\"term\":\"Validity of Licences\",\"fact\":\"Licences are valid from the date of issue.\"},{\"term\":\"Maximum Age Limit for Professional Pilots\",\"fact\":\"With an ATPL, the operating window for a public-transport flight is minimum 21 years — maximum 65 years (answers Q21).\"},{\"term\":\"Privileges of a PPL\",\"fact\":\"Core privilege The privileges of a PPL holder are to act, but not for remuneration, as Pilot-in-Command or Co-pilot of any aeroplane entered in the Aircraft Rating of his licence, and to carry passengers therein.\"}],\"air-regulations/ar-15\":[{\"term\":\"Protecting Visiting Aeroplanes\",\"fact\":\"The ICAO Council has urged Contracting States not to impose on visiting aeroplanes operational requirements other than those established by the State of Registry — provided those State-of-Registry requirements are not lower than the Standards of Annex 6, Part I.\"},{\"term\":\"Recognising a Foreign Airworthiness Certificate\",\"fact\":\"A foreign C of A is recognised only on the condition that the airworthiness requirements under which it was issued or rendered valid are equal to or above the minimum standards that ICAO may establish from time to time.\"},{\"term\":\"National Codes vs ICAO Standards\",\"fact\":\"National codes of airworthiness — containing the full scope and extent of detail that an individual State considers necessary — are required as the basis for the certification of individual aircraft.\"},{\"term\":\"Scope of Annex 8 & the Airworthiness Technical Manual\",\"fact\":\"The level of airworthiness to be maintained by a national code is indicated by the broad Standards of Annex 8, supplemented where necessary by guidance material in ICAO's Airworthiness Technical Manual — Doc 9760.\"},{\"term\":\"Prohibition on Flying & the Special Flight Permit\",\"fact\":\"An aircraft shall NOT be flown during any period for which its C of A or special C of A is suspended or deemed to be suspended.\"}],\"air-regulations/ar-16\":[{\"term\":\"ICAO Annex 6 & Applicability\",\"fact\":\"ICAO Annex 6 is titled \\\"Operation of Aircraft\\\".\"},{\"term\":\"Methods of Carriage of Persons\",\"fact\":\"A part in which cargo or stores are carried, being a part designed to enable a person to have access thereto while the aeroplane is in flight.\"},{\"term\":\"Information Retained on Ground\",\"fact\":\"The same information is carried in a fireproof container in the aeroplane.\"},{\"term\":\"Operator Certification (AOC)\",\"fact\":\"The State in which the operator's principal place of business is located or, if there is no such place of business, the operator's permanent residence.\"},{\"term\":\"Controlling RVR — Touch-down, Mid-point & Stop-end\",\"fact\":\"The touch-down zone (TDZ) RVR is always controlling.\"}],\"air-regulations/ar-17\":[{\"term\":\"Minimum Equipment List (MEL & MMEL)\",\"fact\":\"Aircraft are certified with a great deal of redundant equipment.\"},{\"term\":\"Bird Strike Risk & Avoidance\",\"fact\":\"Hazardous bird concentrations are well known during migration periods on a large temporal and spatial scale, but also occur occasionally throughout the year on a local or regional scale, mainly governed by the diurnal cycle.\"},{\"term\":\"Departure Climb\",\"fact\":\"Operating procedures for the departure climb must ensure flight safety is maintained while minimising noise exposure on the ground.\"},{\"term\":\"Aeroplane Operating Procedures — Approach\",\"fact\":\"Noise preferential routes are established so departing and arriving aeroplanes avoid over-flying noise-sensitive areas near the aerodrome as far as practicable.\"},{\"term\":\"Decompression of a Pressurised Cabin\",\"fact\":\"Cabin pressurisation is the pumping of compressed air into an aircraft cabin to maintain a safe and comfortable environment for crew and passengers when flying at altitude.\"}],\"air-regulations/ar-18\":[{\"term\":\"Q-Code Groups Used in RTF Air-Ground Communications\",\"fact\":\"A Q-code is a three-letter group beginning with \\\"Q\\\", used as a shorthand to either ask a question or give an answer/advice.\"},{\"term\":\"Call Signs for Aeronautical Stations\",\"fact\":\"Every ATS unit has a defined RTF call-sign suffix that tells the pilot exactly what type of service is being provided.\"},{\"term\":\"Transfer of Communication\",\"fact\":\"An aircraft may be instructed to standby on a frequency when the ATSU will initiate communications, and to monitor a frequency on which information is being broadcast.\"},{\"term\":\"Radar Identification of Aircraft\",\"fact\":\"The pilot will be warned if identification is lost, or about to be lost, and appropriate instructions given.\"},{\"term\":\"Runway Visual Range (RVR) / Visibility\",\"fact\":\"The runway designator may be omitted if there is no possibility of confusion.\"}],\"air-regulations/ar-19\":[{\"term\":\"· Objective & Scope of Investigation\",\"fact\":\"The sole objective of the investigation of an accident or serious incident is the prevention of accidents and incidents.\"},{\"term\":\"· ICAO Annex 13 – Key Provisions\",\"fact\":\"The Government of the State in which the accident took place is responsible, under Annex 13 of the Chicago Convention, for the initiation of an accident investigation.\"},{\"term\":\"· Definition of \\\"Serious Incident\\\"\",\"fact\":\"The incidents listed below are typical examples of incidents likely to be serious incidents.\"}],\"air-regulations/ar-20\":[{\"term\":\"· Overview & Purpose of the Annex\",\"fact\":\"The Annex is a wide-ranging document which reflects the flexibility of ICAO in keeping pace with international civil aviation.\"},{\"term\":\"· General Declaration\",\"fact\":\"On those occasions when a General Declaration is required, the information required shall be limited to the format given in Annex 9.\"},{\"term\":\"Electronic Database of Crew Records\",\"fact\":\"Contracting States shall ensure that a record of each crew member's certificates and other official identity documents issued, suspended, or withdrawn is stored in an electronic database, secure from interference and unauthorised access.\"},{\"term\":\"· Standard Forms (Visual Reference)\",\"fact\":\"The three standard documents prescribed by Annex 9 (and reproduced in AIP India) are illustrated below.\"},{\"term\":\"Outgoing Passengers\",\"fact\":\"All passengers leaving India by air are subject to clearance by Custom Authorities.\"}],\"air-regulations/ar-21\":[{\"term\":\"Retention of the Hijacked Aircraft\",\"fact\":\"The Contracting State will make provisions to ensure that an aircraft affected by an unlawful seizure act, which has landed in their territory, would be retained — unless its departure is justified to protect lives.\"},{\"term\":\"Safety of Passengers & Crew After Landing\",\"fact\":\"A State shall take adequate measures for the safety of passengers and crew of an aircraft which is subjected to an act of unlawful interference — until their journey can be continued.\"},{\"term\":\"Potentially Disruptive Passengers\",\"fact\":\"For the transport of potentially disruptive passengers, some supplementary safeguards are to be observed, such as boarding prior to all passengers.\"},{\"term\":\"Mixing & Contact Post-Screening\",\"fact\":\"Once a screened passenger contacts an unscreened person, the integrity of the sterile area is compromised — a prohibited item could have been passed across.\"},{\"term\":\"The Governing Rules — Aircraft (Security) Rules, 2011\",\"fact\":\"Aircraft and airport security in India is governed by the Aircraft (Security) Rules, 2011.\"}],\"air-regulations/ar-22\":[{\"term\":\"The Knowledge Requirement\",\"fact\":\"Part 2 of the Air Regulations book is designed to meet the ICAO requirements of human factor knowledge for the flight crew.\"},{\"term\":\"Why the Human Element Matters\",\"fact\":\"The human element is the most flexible, adaptable and valuable part of the aviation system — but it is also the most vulnerable to influences which can adversely affect its performance.\"},{\"term\":\"Disciplines Frequently Involved in Human Factors Activities\",\"fact\":\"Human Factors are multidisciplinary in nature.\"},{\"term\":\"Accident Rate\",\"fact\":\"The rate of accidents in commercial aviation ( excluding sabotage and acts of terrorism) is approximately 1 accident per million airport movements.\"},{\"term\":\"Human Performance as Root Cause\",\"fact\":\"Most aircraft accidents are linked to deficiencies in human performance.\"}],\"air-regulations/ar-23\":[{\"term\":\"Definition of CRM\",\"fact\":\"CRM is the effective use of all available resources for flight crew personnel to assure a safe and efficient operation, reducing error, avoiding stress, and increasing efficiency.\"},{\"term\":\"Applicability of CRM — Human Factors Framework\",\"fact\":\"CRM is an application of Human Factors (HF) to the flight crew domain.\"},{\"term\":\"Liveware as the Hub — Why the Match Matters\",\"fact\":\"The Liveware (human element) is the HUB of the SHEL model.\"},{\"term\":\"Spotlight — Trans-Cockpit Authority Gradient (TCAG)\",\"fact\":\"A gradient where the captain's authority is recognized, but good relationships and synergistic working are retained.\"},{\"term\":\"TEM Concept\",\"fact\":\"TEM is the practice of thinking ahead in order to predict and avoid errors and operational threats, and to manage any that occur.\"}],\"air-regulations/ar-24\":[{\"term\":\"Receptors & Sensory Memories — Key Features\",\"fact\":\"The sensory stores for sight and sound are the most important, and knowledge of these is necessary.\"},{\"term\":\"Sensory Memory for Sight — Iconic Memory\",\"fact\":\"The Iconic Memory is the visual sensory store.\"},{\"term\":\"Perception\",\"fact\":\"The process of perception is greatly assisted by our ability to form mental and three-dimensional visual models.\"},{\"term\":\"Attention\",\"fact\":\"Attention is the process of directing and focusing psychological resources to enhance perception, performance and mental experience.\"},{\"term\":\"Types of Attention\",\"fact\":\"Selective Attention — inputs are sampled continually to decide their relevance to the present task at hand.\"}],\"air-regulations/ar-25\":[{\"term\":\"The Atmosphere\",\"fact\":\"Human beings live their lives in the lower reaches of the atmosphere where temperatures, pressures and oxygen supply are able to support life.\"},{\"term\":\"Constituent Gases of the Atmosphere\",\"fact\":\"The earth's atmosphere near the surface is composed primarily of Nitrogen and Oxygen.\"},{\"term\":\"Dalton's Law — Law of Partial Pressures\",\"fact\":\"Partial pressures describe the distribution of certain gases in a mixture and follows Dalton's law which states that the total pressure of a mixture of gases is equal to the sum of the partial pressures of the gases which compose the mixture.\"},{\"term\":\"The Physiological Zones of the Atmosphere\",\"fact\":\"The atmosphere is divided — from the pilot's body's point of view — into four functional zones, each demanding a different protective strategy.\"},{\"term\":\"The Central Nervous System (CNS)\",\"fact\":\"The central nervous system consists of the brain and the spinal cord.\"}],\"technical-general/tg-1\":[{\"term\":\"Static Pressure (SP)\",\"fact\":\"Static pressure is the pressure exerted by the air when it is stationary or not moving.\"},{\"term\":\"Temperature\",\"fact\":\"Temperature is a measure of the kinetic energy of the molecules in the air.\"},{\"term\":\"Density (ρ)\",\"fact\":\"Density is the mass of air per unit of volume.\"},{\"term\":\"Dynamic Pressure (q)\",\"fact\":\"Dynamic pressure is the kinetic energy (energy of motion) of the air per unit volume.\"}],\"technical-general/tg-5\":[{\"term\":\"Wing Terminology\",\"fact\":\"High AR wings (long and thin) are found on sailplanes (AR ~35).\"}],\"technical-general/tg-6\":[{\"term\":\"Parasite Drag\",\"fact\":\"Parasite drag includes all types of drag that are not associated with the production of lift.\"},{\"term\":\"Speed Stability\",\"fact\":\"Speed stability refers to an aircraft's tendency to maintain a constant airspeed.\"}],\"technical-general/tg-7\":[{\"term\":\"The Cause of the Stall\",\"fact\":\"A stall is a loss of lift resulting from the separation of airflow from the wing's upper surface.\"},{\"term\":\"Stall Recovery\",\"fact\":\"The only way to recover from a stall is to restore smooth airflow over the wing.\"}],\"technical-general/tg-11\":[{\"term\":\"The Piston Engine\",\"fact\":\"A stroke is defined as the linear distance the piston moves within the cylinder1.\"}],\"technical-general/tg-30\":[{\"term\":\"Tyres\",\"fact\":\"Aircraft tyres are designed to withstand very high loads and speeds.\"}],\"technical-general/tg-32\":[{\"term\":\"Ice Detection and Protection\",\"fact\":\"Anti-icing is the prevention of ice formation.\"}],\"technical-general/tg-34\":[{\"term\":\"Capacitors\",\"fact\":\"A capacitor is a device that stores electrical energy in an electric field.\"}],\"technical-specific/da42-1\":[{\"term\":\"Fuel — what it burns and where it lives\",\"fact\":\"Fuel is carried in an aluminium tank in each wing.\"},{\"term\":\"Avionics — the glass cockpit\",\"fact\":\"The DA-42 NG is built around an integrated glass avionics suite.\"}],\"technical-specific/da42-2\":[{\"term\":\"The EECU — the brain\",\"fact\":\"The engine is managed by an Electronic Engine Control Unit (the EECU, often just \\\"the ECU\\\").\"}],\"technical-specific/da42-3\":[{\"term\":\"Where the fuel lives\",\"fact\":\"Fuel is carried in an aluminium tank inside each wing, each tank made of three chambers linked by a flexible hose and filled from a single filler on the outboard chamber.\"}],\"technical-specific/da42-5\":[{\"term\":\"Steering, brakes and the parking brake\",\"fact\":\"On the ground the nose wheel is steered through the rudder pedals, with a damper to stop shimmy; as the gear retracts the nose wheel centres itself and the steering disconnects to lighten the pedals in flight.\"}],\"technical-specific/da42-6\":[{\"term\":\"The integrated glass cockpit\",\"fact\":\"The DA-42 NG is built around an integrated avionics suite: a Primary Flight Display (PFD), a Multi-Function Display (MFD), an audio panel, an Attitude and Heading Reference System (AHRS) and an Air Data Computer (ADC), all sharing information.\"},{\"term\":\"The GFC 700 autopilot\",\"fact\":\"The autopilot and flight director is the GFC 700 — a three-axis system (pitch, roll and yaw damper) with a flight director.\"}],\"technical-specific/da42-8\":[{\"term\":\"Starting a diesel\",\"fact\":\"Starting is nothing like a piston trainer.\"},{\"term\":\"Take-off and climb\",\"fact\":\"Advance the single power levers smoothly to take-off power — remember that is a five-minute limit.\"},{\"term\":\"Cruise, descent and approach\",\"fact\":\"In the cruise, set continuous power (up to 92% / 2100 RPM) and lean back on the workload — the ECU is managing the engines, the autopilot can fly the profile, and the MFD gives you fuel and range.\"}],\"technical-specific/da42-9\":[{\"term\":\"Engine failure — the multi-engine discipline\",\"fact\":\"An engine failure on a twin is a controllability problem first and a performance problem second.\"},{\"term\":\"Electrical failures\",\"fact\":\"A single alternator failure (L/R ALTN FAIL) is manageable — the other alternator and the battery carry the load, and you reduce non-essential consumers.\"}],\"technical-specific/da42-10\":[{\"term\":\"Single-engine performance\",\"fact\":\"The table you will care about most in real operations is the one-engine-inoperative climb.\"},{\"term\":\"Mass and balance — the method\",\"fact\":\"Weight and balance on this aeroplane is the same arithmetic you already know, referenced to a datum plane set 2.196 m forward of the wing root rib.\"}],\"radio-telephony/rtf-1\":[{\"term\":\"The key definitions you must own\",\"fact\":\"The examiner frequently opens with a definition — \\\"What is the aeronautical mobile service?\\\" — because precise language is the foundation of safe radio work.\"}],\"radio-telephony/rtf-2\":[{\"term\":\"The Chicago Convention (1944)\",\"fact\":\"The Chicago Convention is the founding treaty of international civil aviation — the document that made worldwide flying possible by agreeing common principles between nations.\"},{\"term\":\"ICAO — the global standard-setter\",\"fact\":\"ICAO is the United Nations agency for civil aviation.\"},{\"term\":\"ITU — the keeper of the spectrum\",\"fact\":\"Global radio frequency allocation is partitioned by the ITU, visualized here as orbital spectrum coverage over a borderless globe.\"},{\"term\":\"India's regulators — DGCA, AAI & WPC\",\"fact\":\"ICAO's standards are not law in India until India adopts them.\"},{\"term\":\"Case study: a flight from Delhi to Dubai\",\"fact\":\"Imagine you are departing Delhi for Dubai.\"}],\"radio-telephony/rtf-3\":[{\"term\":\"Licensing the apparatus — WPC, NFAP, SACFA\",\"fact\":\"Aircraft antennas are part of the licensed radio station apparatus and are governed by WPC and DGCA fitment regulations.\"},{\"term\":\"The MEL — flying with an item unserviceable\",\"fact\":\"The MMEL (Master MEL) is produced by the manufacturer/State of design and lists items that may be inoperative for a type.\"}],\"radio-telephony/rtf-4\":[{\"term\":\"Transition altitude & level\",\"fact\":\"Transition Altitude — the altitude at or below which vertical position is expressed as altitude on QNH.\"}],\"radio-telephony/rtf-5\":[{\"term\":\"FIRs, Frequencies & Aeronautical Information\",\"fact\":\"Every flight is built on information someone else collected, published and kept current — the elevation of a runway, the frequency of a beacon, the fact that a taxiway is closed tonight.\"},{\"term\":\"How airspace is divided\",\"fact\":\"Airspace is too vast and varied for one office, one service and one set of rules.\"},{\"term\":\"Indian FIRs & the services\",\"fact\":\"India's airspace is divided into the FIRs of Delhi, Mumbai, Kolkata and Chennai, with the Chennai (Oceanic) region extending far over the Bay of Bengal and Indian Ocean.\"},{\"term\":\"Principal communication & emergency frequencies\",\"fact\":\"Within India you talk to ATC on the VHF aviation band; long-range/oceanic uses HF; and a small set of emergency frequencies is guarded worldwide.\"}],\"radio-telephony/rtf-6\":[{\"term\":\"Meteorological Codes & the Pre-Flight Briefing Service\",\"fact\":\"Weather is the single biggest variable in aviation, and the industry built a compact, coded language to describe it — terse strings that pack an entire weather picture into one line.\"},{\"term\":\"Why weather is coded\",\"fact\":\"Weather decisions are made by crews of every nationality, and the information often crosses a noisy radio or telex link.\"},{\"term\":\"METAR & SPECI — field by field\",\"fact\":\"A METAR is the routine observed weather at an aerodrome, issued at fixed intervals (commonly every 30 or 60 minutes).\"},{\"term\":\"TAF — the aerodrome forecast\",\"fact\":\"A TAF is the forecast for an aerodrome over a validity period, written in the same vocabulary as a METAR but with change groups that say \\\"and then it will become…\\\".\"},{\"term\":\"CAVOK\",\"fact\":\"CAVOK is not just \\\"nice weather\\\" — it has the three defined criteria above.\"}],\"radio-telephony/rtf-7\":[{\"term\":\"Electrical Fundamentals\",\"fact\":\"A radio is, at heart, an electrical machine.\"}],\"radio-telephony/rtf-8\":[{\"term\":\"The spectrum, band by band\",\"fact\":\"The radio spectrum is divided into bands, each a factor of ten in frequency above the one below.\"},{\"term\":\"Channel spacing & capacity\",\"fact\":\"The VHF band is a fixed width, so the number of channels it holds depends on how closely they are spaced.\"},{\"term\":\"Polarization & antenna length\",\"fact\":\"Polarization is the plane of the wave's electric field — vertical or horizontal.\"}],\"radio-telephony/rtf-9\":[{\"term\":\"The sky wave: MUF, LUF & OWF\",\"fact\":\"A wave striking the ionosphere at a shallow (grazing) angle is refracted back over a long distance; a steep angle may punch through.\"},{\"term\":\"Day & night frequencies\",\"fact\":\"By day the D layer is present and absorbs lower frequencies, so you must use a higher HF frequency to get through.\"},{\"term\":\"Skip distance & dead space\",\"fact\":\"Skip distance increases as you raise the frequency (toward the MUF) and as the ionosphere weakens at night — which is why dead space changes through the day.\"},{\"term\":\"The space wave & radio horizon\",\"fact\":\"VHF and above travel in essentially straight lines (the space wave), so range is set by the radio horizon — and the higher you (or the station) are, the farther that horizon.\"}],\"radio-telephony/rtf-10\":[{\"term\":\"The carrier & why we modulate\",\"fact\":\"The carrier wave is a high-frequency wave generated by the transmitter; on its own it carries no information.\"},{\"term\":\"AM — sidebands & modulation depth\",\"fact\":\"In Amplitude Modulation, the height (amplitude) of the carrier is varied in step with the voice, while its frequency stays fixed.\"},{\"term\":\"AM power distribution\",\"fact\":\"Even at full 100% modulation, two-thirds of the transmitted power sits in the carrier, which carries no information; only one-third is shared between the two sidebands.\"},{\"term\":\"FM — Frequency Modulation\",\"fact\":\"In FM the carrier's frequency is varied in step with the voice while its amplitude stays constant.\"},{\"term\":\"Emission designators\",\"fact\":\"An emission is classified by three symbols: type of modulation &middot; nature of the signal &middot; type of information.\"}],\"radio-telephony/rtf-11\":[{\"term\":\"Radio Equipment & Operation\",\"fact\":\"Everything so far has been theory; this chapter is your hands on the equipment.\"},{\"term\":\"The audio panel & intercom\",\"fact\":\"An intercom conversation is internal — it does not go out on the radio.\"},{\"term\":\"Squelch, AVC, volume & tuning\",\"fact\":\"Squelch — mutes the constant background hiss when no signal is present, opening the audio only when a real signal arrives.\"},{\"term\":\"Antennas & matching\",\"fact\":\"The VHF COM antenna is the vertical blade — sized to a fraction of the wavelength and matched to the vertically-polarized VHF signal.\"}],\"radio-telephony/rtf-12\":[{\"term\":\"The ground station (NDB)\",\"fact\":\"The Non-Directional Beacon is the simplest radio aid: a ground transmitter that radiates equally in all directions (hence \\\"non-directional\\\").\"},{\"term\":\"ILS — Instrument Landing System\",\"fact\":\"The ILS is a precision approach aid giving the pilot both azimuth (left/right of the centreline) and vertical (above/below the glide path) guidance down to low height, plus distance checkpoints.\"},{\"term\":\"Primary radar & radar principles\",\"fact\":\"Primary Surveillance Radar (PSR) is the original radar: transmit a pulse, listen for the reflected echo from the target, and time it.\"},{\"term\":\"ACAS / TCAS\",\"fact\":\"ACAS (the ICAO term; TCAS II is the common implementation) interrogates the transponders of nearby aircraft — exactly like a tiny airborne SSR — and tracks their range, closure and altitude.\"}],\"radio-telephony/rtf-13\":[{\"term\":\"The number rules\",\"fact\":\"Whole hundreds and whole thousands are transmitted by pronouncing each digit in the number of hundreds/thousands followed by HUNDRED or THOUSAND — used for altitudes, heights, cloud heights and visibility.\"}],\"radio-telephony/rtf-14\":[{\"term\":\"Call Signs & Establishing Communication\",\"fact\":\"On a busy frequency a dozen aircraft may be listening at once, so every transmission must say who is calling and who is being called — unambiguously, every time.\"},{\"term\":\"Ground-station call signs — the suffix names the service\",\"fact\":\"A ground station's call sign is the place name + a suffix, and the suffix tells you which service you have reached.\"}],\"radio-telephony/rtf-15\":[{\"term\":\"The aerodrome controller\",\"fact\":\"Aerodrome control ( Tower) is responsible for traffic on the runways and in the aerodrome traffic circuit, and for vehicles and aircraft on the manoeuvring area.\"},{\"term\":\"Clearance & departure information\",\"fact\":\"An IFR departure clearance is a contract: it states where you are cleared, by what route, to what level, and the squawk.\"},{\"term\":\"The aerodrome traffic circuit\",\"fact\":\"The circuit is the standard rectangular pattern flown around a runway.\"}],\"radio-telephony/rtf-16\":[{\"term\":\"Why vehicles talk to the tower\",\"fact\":\"Any vehicle operating on the manoeuvring area (runways and taxiways) needs ATC clearance for its movements; vehicles confined to the apron are normally handled by apron management.\"},{\"term\":\"Crossing & holding short of runways\",\"fact\":\"A vehicle crossing a runway is the highest-risk vehicle movement, so the phraseology is strict and explicit.\"}],\"radio-telephony/rtf-17\":[{\"term\":\"Approach Control\",\"fact\":\"Approach control owns the busy transition between the runway and the en-route world — sequencing arrivals down to final, launching departures up to the airways, and, where there is no ILS, talking an aircraft all the way to the runway by radar.\"},{\"term\":\"What approach control does\",\"fact\":\"Approach control (\\\"Approach\\\", \\\"Radar\\\", \\\"Director\\\") handles aircraft in the terminal area — climbing departures handed up from Tower until they reach the airways, and descending arrivals handed down from Area control until they are established on final and passed to Tower.\"}],\"radio-telephony/rtf-19\":[{\"term\":\"Radar assistance to a comms-failure aircraft\",\"fact\":\"Even with no voice, a working transponder turns your aircraft from a guess into a tracked, instructable target — which is why you keep the transponder ON and squawk 7600 the moment a radio fails (full procedure in Chapter 20).\"}],\"radio-telephony/rtf-20\":[{\"term\":\"Imposition & termination of silence\",\"fact\":\"To keep the frequency clear for the distress, silence is imposed: in the aeronautical service the signal is \\\" STOP TRANSMITTING, MAYDAY \\\", from the controlling station (or the aircraft in distress), addressed to all stations or to the one interfering.\"}],\"radio-telephony/rtf-21\":[{\"term\":\"RVR — what and why\",\"fact\":\"RVR is the distance over which the pilot of an aircraft on the centreline of a runway can see the runway surface markings, or the lights delineating the runway or identifying its centreline.\"},{\"term\":\"Transmission of RVR\",\"fact\":\"For a long runway, RVR is measured and passed at up to three points: the touchdown zone, the midpoint, and the stop-end.\"}],\"radio-telephony/rtf-22\":[{\"term\":\"ATIS — the local picture\",\"fact\":\"ATIS is the continuous broadcast of recorded non-control information in selected high-activity terminal areas.\"},{\"term\":\"VOLMET — the regional picture\",\"fact\":\"VOLMET (meteorological information for aircraft in flight) is a continuous or scheduled voice broadcast of meteorological information for several aerodromes in a region.\"}],\"instrumentation/inst-1\":[{\"term\":\"Ergonomy & Standard Panel Layouts\",\"fact\":\"Ergonomy (human engineering) is the science of the relationship between people and machines.\"}],\"instrumentation/inst-2\":[{\"term\":\"Pitot / Static Heads\",\"fact\":\"A static head is a tube with its forward end sealed but with holes or slots in the sides.\"},{\"term\":\"Requirements of a Pitot Tube\",\"fact\":\"Air is either brought to rest against a stagnation wall then piped to the ASI/Machmeter, or passed directly up the pitot pipelines (more usual in elementary aircraft).\"},{\"term\":\"Requirements of a Static Source\",\"fact\":\"The static source — whether a simple hole or a combined probe — should have its opening at right angles to the airflow, so only static pressure is sensed with no dynamic component.\"},{\"term\":\"Position Error & the Static Vent\",\"fact\":\"With forward motion the sensed static pressure is slightly low due to suction; as speed increases, turbulent airflow near the heads makes the error grow.\"},{\"term\":\"The static vent\",\"fact\":\"Advantages of the static vent: airflow at the vents is less turbulent so static pressure is more accurate; errors when side-slipping or yawing are reduced; and duplicating vents on each side ( cross-balancing) further reduces side-slip/yaw errors.\"}],\"instrumentation/inst-3\":[{\"term\":\"Total Air Temperature (TAT) Probe\",\"fact\":\"The TAT probe is a small strut and air intake made of nickel-plated beryllium copper — chosen for good thermal conductivity and mechanical strength.\"},{\"term\":\"Calibration and the International Standard Atmosphere (ISA)\",\"fact\":\"Due to the variable nature of the real atmosphere, a standard calibration model is used.\"}],\"instrumentation/inst-4\":[{\"term\":\"Equivalent Airspeed (EAS)\",\"fact\":\"EAS is the most accurate measure of dynamic pressure over the wing.\"},{\"term\":\"True Airspeed (TAS)\",\"fact\":\"TAS is the actual speed of the aircraft relative to the surrounding air mass.\"},{\"term\":\"Pitot Head Blockage\",\"fact\":\"Special case: If both the ram air input AND the drain hole are blocked (static port open), the locked pitot pressure causes the ASI to react like an altimeter — reading increases during a climb and decreases during a descent.\"},{\"term\":\"Static Leak — Unpressurised Aircraft\",\"fact\":\"In an unpressurised aircraft, if the static leak occurs where the outside pressure is lower than the sensed static pressure (almost always the case aerodynamically), a false lower pressure is sensed around the capsule.\"}],\"instrumentation/inst-5\":[{\"term\":\"Servo-Assisted Altimeters\",\"fact\":\"Most counter-pointer altimeters are servo-assisted.\"},{\"term\":\"E-bar / I-bar Operation\",\"fact\":\"AC is fed to the middle leg of the E-bar, setting up alternating magnetic fields in legs A and B.\"},{\"term\":\"Time Lag\",\"fact\":\"Lag is most noticeable with rapid, prolonged altitude changes.\"},{\"term\":\"Regional QNH (Lowest Forecast QNH)\",\"fact\":\"Setting Regional QNH causes the altimeter to under-read (aircraft is shown as lower than actual) — erring on the safe side for terrain clearance.\"},{\"term\":\"Density Altitude\",\"fact\":\"Density Altitude is defined as the altitude in the Standard Atmosphere at which the prevailing density would occur; alternatively, the altitude in the Standard Atmosphere corresponding to the prevailing pressure and temperature.\"}],\"instrumentation/inst-6\":[{\"term\":\"VSI Metering Unit\",\"fact\":\"The altitude compensation in the VSI is provided by the capillary and orifice combination in the metering unit — not a bimetallic temperature sensor.\"},{\"term\":\"Position (Pressure) Error\",\"fact\":\"A VSI climb indication during the take-off roll caused by position error does not mean the aircraft is climbing — do not react to it until established in the climb.\"}],\"instrumentation/inst-7\":[{\"term\":\"Speed of Sound\",\"fact\":\"The speed of sound is not constant — it varies with air temperature only, not pressure or density directly.\"},{\"term\":\"Position Error at High Mach Numbers\",\"fact\":\"The Machmeter is NOT affected by temperature or density errors.\"},{\"term\":\"Blockages\",\"fact\":\"Effect of pitot and static blockages on Machmeter readings — note these are identical to ASI blockage effects.\"}],\"instrumentation/inst-8\":[{\"term\":\"Failure Warning\",\"fact\":\"A warning flag appears on the affected ADS instrument if there is loss of valid data or an internal failure.\"},{\"term\":\"Reduced Instrument and Lag Errors\",\"fact\":\"Friction loss in mechanical linkages is the major source of instrument error in conventional instruments, also causing lag.\"}],\"instrumentation/inst-9\":[{\"term\":\"The Magnet and Magnetic Field\",\"fact\":\"The magnetic field of a magnet is the space around it in which its magnetic influence is felt.\"},{\"term\":\"Poles of a Magnet – Red and Blue Poles\",\"fact\":\"By convention, magnetic lines of force are directed out from the red pole and back in to the blue pole.\"},{\"term\":\"Field Strength and Directive Force\",\"fact\":\"The horizontal component H is called the directive force — it is the component that aligns the compass needle with the magnetic meridian, providing the directional reference.\"},{\"term\":\"Secular Change (most significant)\",\"fact\":\"The most significant regular change is secular change — caused by the slow movement of the magnetic poles about the geographic poles.\"}],\"instrumentation/inst-10\":[{\"term\":\"The Vertical Card Compass\",\"fact\":\"The vertical card compass (B-type / E-type) is the standard direct reading compass for general use — the main magnetic heading reference in light aircraft and the standby compass in larger aircraft.\"},{\"term\":\"Compass Requirements – Horizontality, Sensitivity, Aperiodicity\",\"fact\":\"The three key requirements of a direct reading compass and how each is achieved.\"},{\"term\":\"The Compass Liquid\",\"fact\":\"The liquid is essential — it dampens oscillations and lubricates the pivot.\"},{\"term\":\"Deviation and Accuracy\",\"fact\":\"Deviation is produced by the iron/steel components in the aircraft distorting the earth's field.\"},{\"term\":\"Acceleration and Turning Errors – Theory\",\"fact\":\"No error occurs when the manoeuvre displaces the CG north or south (in the plane of the magnetic meridian) — only the north-south tilt changes, with no azimuth rotation.\"}],\"instrumentation/inst-11\":[{\"term\":\"Gyroscopes – Introduction and Basic Properties\",\"fact\":\"The simplest gyroscope (gyro) is a rapidly spinning disc (rotor).\"},{\"term\":\"Gimbals and Degrees of Freedom\",\"fact\":\"For a gyro to maintain its direction while attached to a manoeuvring aircraft, it needs suspension devices that allow the aircraft to move around it — these are called gimbals.\"},{\"term\":\"Relationship Between Precession and Rigidity\",\"fact\":\"Precession and rigidity are opposite characteristics.\"},{\"term\":\"Wander – Drift and Topple\",\"fact\":\"Any departure of a gyro axis from its original orientation is called wander.\"},{\"term\":\"Transport Wander\",\"fact\":\"Transport wander is equivalent to the difference in meridian alignment between the departure and arrival points — in effect, the convergence of meridians.\"}],\"instrumentation/inst-12\":[{\"term\":\"Second Control System — Wedge Plate\",\"fact\":\"Air spinning the rotor flows round the rotor inside a metal case and is directed at a wedge plate fixed to the outer gimbal.\"},{\"term\":\"The Caging Device\",\"fact\":\"On the front of the instrument there is a caging knob which, when pushed in, moves a caging arm that locks the inner gimbal at right angles to the outer gimbal (locking the rotor axis in the yawing plane).\"},{\"term\":\"Gimballing Errors\",\"fact\":\"Gimballing errors are errors in DGI indications which occur when bank is applied.\"},{\"term\":\"Apparent Wander Due to Rotation of the Earth\",\"fact\":\"At the equator, an observer and gyro aligned N/S will move with the earth through 360° in 24 hours with no change in rotor axis direction relative to the meridian — so there is zero apparent drift at the equator.\"},{\"term\":\"Latitude Nut Correction\",\"fact\":\"Compensation for apparent wander due to the earth's rotation is by means of an adjustable latitude rider nut on a threaded stud fixed horizontally to the inner gimbal.\"}],\"instrumentation/inst-13\":[{\"term\":\"Control System — Pendulous Vanes\",\"fact\":\"Four slots and four pendulous (hanging) vanes are at the base of the rotor housing.\"},{\"term\":\"The Electric Artificial Horizon\",\"fact\":\"The main advantage of the electric artificial horizon is its greater rigidity due to its faster spin rate ( 22,500 rpm typical vs.\"}],\"instrumentation/inst-14\":[{\"term\":\"The Rate Gyro — Principle\",\"fact\":\"The horizontal-axis rate gyro; one gimbal; one degree of freedom; why a low rotor speed is desirable.\"},{\"term\":\"Operation — Spring and Precession Equilibrium\",\"fact\":\"The chain of events from turn entry to equilibrium; how the scale is calibrated.\"},{\"term\":\"TAS Calibration and Error\",\"fact\":\"Calibration of correct rate of turn (spring tension) is optimized for a design TAS.\"},{\"term\":\"The Slip Indicator\",\"fact\":\"The slip indicator indicates whether a turn is properly balanced (correct bank angle for TAS and rate of turn), or whether the aircraft is slipping in or skidding out.\"}],\"instrumentation/inst-15\":[{\"term\":\"Gyroscope Axis Orientation — 30° Inclination\",\"fact\":\"In the standard TBI, the rate gyro axis is horizontal — the gyro is sensitive to yaw (turning about the vertical axis) only.\"}],\"instrumentation/inst-16\":[{\"term\":\"Deviation — Definition and Sign Convention\",\"fact\":\"Deviation is the angular difference measured between the direction taken up by a compass needle and the magnetic meridian, caused by the aircraft's own internal magnetism deflecting the needle.\"},{\"term\":\"Compass Swing — Purpose and Procedure\",\"fact\":\"A compass swing is the basic method of determining deviation by comparing the aircraft's heading compass reading with magnetic heading as defined by a high quality 'land or datum' compass, carried out in an area specifically selected for this purpose.\"},{\"term\":\"Hard Iron Magnetism\",\"fact\":\"Hard iron magnetism consists of permanent magnets in the aircraft structure — parts that retain their magnetism independently of any external field.\"},{\"term\":\"Soft Iron Magnetism (Vertical Soft Iron)\",\"fact\":\"Soft iron magnetism is induced in parts of the aircraft structure by surrounding fields — most importantly the earth's magnetic field.\"},{\"term\":\"Correction of Coefficients\",\"fact\":\"Coefficient B: Corrected by adjusting compensating magnets on an easterly or westerly heading (where B deviation is maximum).\"}],\"instrumentation/inst-17\":[{\"term\":\"Direct Reading Magnetic Compass (DRMC) Limitations\",\"fact\":\"Magnetic sensing element is within the instrument, close to the pilot — hence close to deviation sources (lights, motors, ferrous metal in the cockpit).\"},{\"term\":\"Directional Gyro Indicator (DGI) Limitations\",\"fact\":\"No magnetic element — if the gyro drifts, there is no correction except by the pilot manually synchronizing to the DRMC at regular intervals.\"},{\"term\":\"Operation with Steady Heading — Gyro Drift Correction\",\"fact\":\"The flux valve senses the earth's magnetic field and reproduces it within the compass unit, where it is compared with the position of the gyro drive shaft.\"},{\"term\":\"Detector Unit — The Flux Valve\",\"fact\":\"The detector unit is positioned in a part of the aircraft least affected by on-board electrical fields — usually the wing tip or tail fin, where aircraft-generated magnetic disturbances are at a minimum.\"},{\"term\":\"Flux Valve — How It Works (Faraday's Law)\",\"fact\":\"The electromagnetic principle of the flux valve; why 3 legs are needed; output characteristics.\"}],\"instrumentation/inst-18\":[{\"term\":\"The Platform\",\"fact\":\"The platform is a gimbal assembly that allows the aircraft to go through any attitude change while the inner element (carrying the accelerometers and gyros) remains earth-level.\"}],\"instrumentation/inst-19\":[{\"term\":\"Accuracy\",\"fact\":\"Accuracy is directly influenced by the length of the optical path.\"},{\"term\":\"Dither Motor (Piezo-electric)\",\"fact\":\"Dither is used to break the frequency lock (lock-in) which would prevent small rotational rates from being sensed.\"}],\"instrumentation/inst-20\":[{\"term\":\"Height Scale\",\"fact\":\"The scale is logarithmic: expanded from 0–500 ft, then non-linear from 500–2500 ft.\"}],\"instrumentation/inst-21\":[{\"term\":\"Control and Display Unit (CDU)\",\"fact\":\"The CDU is the interface between the aircraft and crew.\"}],\"instrumentation/inst-22\":[{\"term\":\"Failure Annunciation\",\"fact\":\"Failure of data signals (ILS, radio altimeter, etc.) is displayed on each EADI and EHSI as yellow flags \\\"painted\\\" at specific matrix locations on the CRT screens.\"}],\"instrumentation/inst-24\":[{\"term\":\"Data Link\",\"fact\":\"A data link is a means of connecting one location to another for transmitting and receiving information.\"},{\"term\":\"FANS B — High Density Airspace\",\"fact\":\"FANS B is very similar to FANS A but operates within high density airspace with good VHF coverage.\"}],\"instrumentation/inst-26\":[{\"term\":\"Types of Autopilot (Axes)\",\"fact\":\"Single, two, and three axis autopilot systems and which axis is primary.\"},{\"term\":\"EU-OPS Requirements\",\"fact\":\"An operator shall not conduct single pilot IFR operations unless the aeroplane is equipped with an autopilot with at least ALTITUDE HOLD and HEADING MODE.\"},{\"term\":\"Autopilot Limitations & Gain Adaption\",\"fact\":\"Normal A/P pitch/roll limits and why gain adaption is needed.\"}],\"instrumentation/inst-27\":[{\"term\":\"Radio Altimeter Role\",\"fact\":\"Altitude information for vertical guidance to touchdown is always provided by radio altimeter, which becomes effective as soon as altitude is within its operating range (typically 2500 feet).\"},{\"term\":\"Alert Height\",\"fact\":\"The Alert Height is a specified radio height, based on the aircraft's characteristics and its fail-operational landing system.\"}],\"instrumentation/inst-28\":[{\"term\":\"ARM Mode\",\"fact\":\"Annunciated ARM when A/T Arm switch is at ARM and no A/T mode is engaged.\"},{\"term\":\"Go-around Mode\",\"fact\":\"A/T GA mode is armed when descending below 2000 ft RA (with or without AFDS).\"},{\"term\":\"Flexible Take-off\",\"fact\":\"Reduced-power (flexible) take-off and how it is achieved with the autothrottle.\"},{\"term\":\"Achieving Reduced Thrust with A/T\",\"fact\":\"The higher \\\"assumed temperature\\\" fools the FADEC/thrust computation system into thinking the day is hotter, which corresponds to less available engine thrust — thus the system limits to a lower N1/EPR, producing the desired reduced thrust.\"},{\"term\":\"Turbulence\",\"fact\":\"The autothrottle is NOT to be used in severe turbulence.\"}],\"instrumentation/inst-29\":[{\"term\":\"Dutch Roll — The Problem the Yaw Damper Solves\",\"fact\":\"Dutch Roll is an oscillatory motion consisting of a combination of yawing and rolling.\"},{\"term\":\"Why Altitude Worsens Dutch Roll\",\"fact\":\"At altitude, True Air Speed (TAS) is much higher for the same Indicated Air Speed (IAS).\"},{\"term\":\"Rate Gyro Sensing\",\"fact\":\"The core sensor is a yaw rate gyro that measures the angular rate of yaw.\"},{\"term\":\"Phase Advance Circuit\",\"fact\":\"The phase advance circuit shifts the control signal forward in phase, so the corrective rudder deflection is applied at the point of maximum yaw rate (not at the peak displacement angle).\"},{\"term\":\"Filter Characteristics\",\"fact\":\"Exam Trap: \\\"During a constant-rate turn, the Dutch Roll filter output is ZERO.\\\" — the filter sees a steady, unchanging yaw rate and produces no rudder demand.\"}],\"instrumentation/inst-30\":[{\"term\":\"Boeing 737-400 Reversion Modes\",\"fact\":\"Automatic reversion to a more effective AFDS/A/T combination when speed control alone is insufficient.\"}],\"instrumentation/inst-33\":[{\"term\":\"Altitude Alerting System\",\"fact\":\"Warns pilots that the aircraft is approaching or deviating from the selected altitude.\"},{\"term\":\"Warning Types\",\"fact\":\"Stall warning must continue until AoA is reduced to approximately that at which it was initiated.\"},{\"term\":\"Stall Protection\",\"fact\":\"Deep Stall (T-tail): T-tail aircraft can enter a deep stall from which there is little or no chance of recovery — hence the stick-pusher is particularly important for these types.\"},{\"term\":\"Landing Configuration Warning\",\"fact\":\"Audible warning if throttles are retarded without the landing gear locked down (and may also warn for flaps).\"}],\"instrumentation/inst-34\":[{\"term\":\"Mode 3 — Altitude Loss after Take-off or Go-around\",\"fact\":\"Alerts if a descent is made during initial climb or go-around.\"},{\"term\":\"Mode 4B — Unsafe Terrain Clearance (Flaps Not Landing)\",\"fact\":\"Activates when gear is down and flaps are NOT in landing position.\"}],\"instrumentation/inst-35\":[{\"term\":\"No Bearing Advisories\",\"fact\":\"No bearing information does NOT degrade TCAS ability to compute a TA or RA — only the display position is affected.\"}],\"instrumentation/inst-36\":[{\"term\":\"Parameters Recorded\",\"fact\":\"The mandatory parameters recorded on the FDR depend on the age and size of the aircraft and are specified in OPs Regulations.\"},{\"term\":\"Dispatch with Inoperative FDR\",\"fact\":\"Any CVR required to be carried is operative (unless it is combined with the FDR).\"}],\"instrumentation/inst-37\":[{\"term\":\"What the CVR Records\",\"fact\":\"The CVR must record from before the aircraft is capable of moving under its own power until it is no longer able to do so.\"},{\"term\":\"The Control Unit\",\"fact\":\"The control unit is mounted on the flight deck, usually in the roof (overhead) panel.\"}],\"instrumentation/inst-38\":[{\"term\":\"Engine Pressure Ratio (EPR) Gauge\",\"fact\":\"On some large turbofan engines, an integrated EPR is produced by comparing the integrated turbine discharge pressure and fan outlet pressure against the compressor inlet pressure.\"},{\"term\":\"Engine Torque (Turboprop/Turboshaft)\",\"fact\":\"Torque is measured between the engine and the reduction gearbox.\"},{\"term\":\"Fuel Flowmeter\",\"fact\":\"The flowmeter is located in the high-pressure fuel line to the burners.\"},{\"term\":\"Remote Signal Transmission & Flight Hour Meter\",\"fact\":\"Remote indicating systems are used to indicate the position of valves, flaps, or levers on engines to the cockpit.\"}],\"radio-navigation/rnav-1\":[{\"term\":\"Circular Polarization\",\"fact\":\"Two Key Advantages of Circular Polarization (Exam Favourite) Rain clutter elimination in radar: When circularly polarized energy is reflected from water droplets, the circularity of the returned signal is reversed.\"},{\"term\":\"Radio Waves & The Period\",\"fact\":\"The sinusoidal nature of radio waves, the period (τ), how frequency is derived from period, the units Hz/kHz/MHz/GHz, and how to perform frequency–wavelength conversions using the core formula.\"},{\"term\":\"Phase Comparison\",\"fact\":\"The concept of phase, the requirements for a valid phase comparison (same frequency), how to determine phase difference graphically and mathematically, and why phase comparison is used in navigation systems such as VOR and ILS.\"}],\"radio-navigation/rnav-2\":[{\"term\":\"Attenuation\",\"fact\":\"Attenuation is the term for the loss of signal strength in a radio wave as it travels outward from the transmitter.\"},{\"term\":\"Static Interference\",\"fact\":\"Large amounts of static electricity are generated in the atmosphere by weather, human activity, and geological activity.\"},{\"term\":\"Factors Affecting Surface Wave Range\",\"fact\":\"A horizontally polarized wave is attenuated very quickly.\"},{\"term\":\"Space Wave\",\"fact\":\"At frequencies of VHF and above, radio waves start to behave more like visible light — there is a radio horizon just as there is a visual horizon.\"},{\"term\":\"Maximum Usable Frequency (MUF)\",\"fact\":\"The MUF for a given range is the frequency of the first returning sky wave.\"}],\"radio-navigation/rnav-3\":[{\"term\":\"Heterodyning & Sidebands\",\"fact\":\"The process of combining RF and AF signals is called heterodyning.\"},{\"term\":\"Phase Modulation\",\"fact\":\"In Phase Modulation, the phase of the carrier wave is modified by the input signal.\"},{\"term\":\"Analogue Phase Modulation\",\"fact\":\"The phase of the carrier is modified in proportion to the amplitude of the analogue input signal — similar to AM but it is the phase angle that changes rather than the amplitude or frequency.\"},{\"term\":\"Pulse Modulation\",\"fact\":\"Pulse modulation is formed by generating and transmitting a sequence of short-period pulses — the carrier wave is transmitted in intermittent bursts rather than continuously.\"},{\"term\":\"Emission Designators\",\"fact\":\"Emission designators are a standardised three-character code (letter-digit-letter) that describe the characteristics of an electronic transmission.\"}],\"radio-navigation/rnav-4\":[{\"term\":\"Basic Principles — Dipole & Marconi Aerials\",\"fact\":\"The two fundamental antenna types for basic communications — the half-wave dipole and the quarter-wave Marconi (which is used on aircraft).\"},{\"term\":\"Aerial Feeders\",\"fact\":\"The means of carrying RF energy between the aerial and equipment depends on frequency and power level.\"}],\"radio-navigation/rnav-6\":[{\"term\":\"Bearing Accuracy Classes\",\"fact\":\"The four accuracy classes (A–D), what accuracy to assume when no class is given, and the accuracy of modern Doppler-based VDF.\"}],\"radio-navigation/rnav-7\":[{\"term\":\"Non-Directional Beacon (NDB)\",\"fact\":\"Cone of Silence When the aircraft is directly overhead the NDB, no signal is received and the ADF needle will swing erratically.\"},{\"term\":\"Loop Aerial\",\"fact\":\"A voltage is generated in the vertical elements of a loop aerial due to the phase difference of the incoming wave across the loop.\"},{\"term\":\"Sense Aerial — Resolving Ambiguity\",\"fact\":\"To resolve the ambiguity, a simple dipole (sense) aerial is added.\"},{\"term\":\"Cardioid — Single Null\",\"fact\":\"Dual Cardioid Switching A single cardioid null is not precise enough for ICAO ±5° accuracy.\"},{\"term\":\"Fixed Loop / Goniometer\",\"fact\":\"In practice, a rotating loop outside the aircraft is not feasible.\"}],\"radio-navigation/rnav-8\":[{\"term\":\"DOC — Designated Operational Coverage\",\"fact\":\"VOR DOC is valid day and night — VHF is not affected by skywave.\"}],\"human-performance/front-matter\":[{\"term\":\"How to Use This Book\",\"fact\":\"The book is built in eleven modules and twenty-six chapters, running from the air outside the aircraft to the mind inside the pilot.\"}],\"human-performance/hpl-1\":[{\"term\":\"What Human Performance & Limitations Is\",\"fact\":\"Human Performance & Limitations (HPL) is the applied study of human behaviour, physiology and psychology as they relate to the operation of an aircraft, and of how those human factors influence the safety and efficiency of flight.\"},{\"term\":\"Why the Human Fails\",\"fact\":\"Start from an uncomfortable truth the examiner expects you to state plainly: human error is inevitable.\"}],\"human-performance/hpl-2\":[{\"term\":\"The Atmosphere\",\"fact\":\"Human beings live their lives in the lower reaches of the atmosphere where temperatures, pressures and oxygen supply are able to support life.\"},{\"term\":\"Constituent Gases of the Atmosphere\",\"fact\":\"The earth's atmosphere near the surface is composed primarily of Nitrogen and Oxygen.\"},{\"term\":\"Dalton's Law — Law of Partial Pressures\",\"fact\":\"Partial pressures describe the distribution of certain gases in a mixture and follows Dalton's law which states that the total pressure of a mixture of gases is equal to the sum of the partial pressures of the gases which compose the mixture.\"}],\"human-performance/hpl-3\":[{\"term\":\"The Physiological Zones of the Atmosphere\",\"fact\":\"The atmosphere is divided — from the pilot's body's point of view — into four functional zones, each demanding a different protective strategy.\"}],\"human-performance/hpl-4\":[{\"term\":\"The Central Nervous System (CNS)\",\"fact\":\"The central nervous system consists of the brain and the spinal cord.\"},{\"term\":\"The Autonomic Nervous System (ANS)\",\"fact\":\"The organs (the \\\"viscera\\\") of our body — such as the heart, stomach and intestines — are regulated by a part of the nervous system called the Autonomic Nervous System (ANS).\"}],\"human-performance/hpl-5\":[{\"term\":\"Internal / Tissue Respiration\",\"fact\":\"Internal or Tissue Respiration refers to the transfer of Oxygen from the blood to the tissues of the body.\"},{\"term\":\"Breathing\",\"fact\":\"Normal breathing is a purely automatic process under the unconscious control of the nervous system.\"},{\"term\":\"Left Side of the Heart\",\"fact\":\"Blood's journey from left ventricle to capillaries Blood containing oxygen is pumped around the body from the left ventricle.\"},{\"term\":\"Pulse Rate\",\"fact\":\"The normal rate of the pulse is the rate of the heartbeat.\"},{\"term\":\"If you lose a lot of blood…\",\"fact\":\"Sometimes is enough to keep the body going until it can produce new blood cells and other blood elements.\"}],\"human-performance/hpl-6\":[{\"term\":\"HYPOXIA\",\"fact\":\"The term cerebral hypoxia technically refers to lack of oxygen supply to the cerebral hemispheres (the outer portion of the brain).\"}],\"human-performance/hpl-7\":[{\"term\":\"Causes at Low Altitude\",\"fact\":\"At low altitude — where hypoxia is not a factor — the most common causes of hyperventilation are psychological or environmental rather than physiological.\"},{\"term\":\"Treatment of Hyperventilation\",\"fact\":\"One of the direct causes of hyperventilation is a reduction in the carbon dioxide level in the blood.\"}],\"human-performance/hpl-8\":[{\"term\":\"Donating Blood — the 48-hr rule\",\"fact\":\"In a completely healthy individual, the fluid reduction caused by donating one unit of blood is replaced within several hours.\"},{\"term\":\"What TUC / EPT is\",\"fact\":\"Time of useful consciousness (TUC), also effective performance time (EPT), is defined as the amount of time an individual is able to function effectively (e.g., perform flying duties) in an environment of inadequate oxygen supply.\"},{\"term\":\"Why TUC Drops Sharply at Altitude\",\"fact\":\"At the higher altitudes, the TUC becomes very short; considering this danger, the emphasis is on PREVENTION rather than CURE.\"},{\"term\":\"The 8,000 ft \\\"Maximum Comfort\\\" Rule\",\"fact\":\"The maximum altitude without oxygen at which flying efficiency is not impaired is 8,000 feet.\"},{\"term\":\"Atmospheric Pressure is Halved at 18,000 ft\",\"fact\":\"As the aircraft climbs, atmospheric pressure is reduced.\"}],\"human-performance/hpl-9\":[{\"term\":\"The 3,000-ft Penalty — 10,000 ft becomes 7,000 ft\",\"fact\":\"A pilot who is also a smoker may experience the symptoms of oxygen deprivation, or hypoxia, at a lower altitude ( 7,000 ft) than a non-smoker ( 10,000 ft).\"},{\"term\":\"Alcohol\",\"fact\":\"The headline — alcohol is a depressant Alcohol acts primarily as a depressant.\"},{\"term\":\"The 24-Hour Bottle-to-Throttle Rule\",\"fact\":\"An excellent rule is to allow TWENTY-FOUR HOURS between the last drink and takeoff time.\"},{\"term\":\"Alcohol Metabolism — The Fixed Rate\",\"fact\":\"For men, this is usually a rate of about ONE STANDARD DRINK PER HOUR.\"}],\"human-performance/hpl-10\":[{\"term\":\"Aircraft Humidifier Systems\",\"fact\":\"Aircraft such as the Airbus A350, Boeing 787, and the future Boeing 777X are compatible with onboard humidifiers, either in crew areas or the entire cabin.\"},{\"term\":\"Why Pilot Incapacitation is a Flight-Safety Issue\",\"fact\":\"The risk of seizure in flight is obvious.\"},{\"term\":\"Obvious vs Subtle — Why Subtle is MORE Dangerous\",\"fact\":\"With subtle incapacitation, the captain is still moving switches, talking on the radio, even responding to questions — but his judgement is impaired.\"},{\"term\":\"Epilepsy — Grand Mal & Petit Mal\",\"fact\":\"A fit or seizure is usually referred to as \\\"epilepsy\\\".\"},{\"term\":\"Faint & Vasovagal Syncope\",\"fact\":\"Faint is a common cause of a loss of consciousness in adults.\"}],\"human-performance/hpl-11\":[{\"term\":\"The Cornea, Iris & Pupil, Lens\",\"fact\":\"The amount of light allowed to enter the eye is controlled by the Iris.\"},{\"term\":\"The Retina — Rods, Cones, and the Fovea\",\"fact\":\"The Retina is a light sensitive screen lining the inside of the eyeball.\"},{\"term\":\"The Rods\",\"fact\":\"The Rods can only detect black and white but are much more sensitive at lower light levels.\"},{\"term\":\"The Cones & The Fovea\",\"fact\":\"The central part of the retina is called the FOVEA.\"},{\"term\":\"Eye Movement & Binocular Vision\",\"fact\":\"Binocular Vision means seeing with two eyes.\"}],\"human-performance/hpl-12\":[{\"term\":\"The Blind Spot\",\"fact\":\"The blind spot is point on the retina where the optic nerve enters the eyeball.\"},{\"term\":\"Empty Visual Field (Empty Field Myopia)\",\"fact\":\"In the absence of anything to focus on (that is when your visual field is empty), the natural focus point of the eye is, on average, at a distance of between 1 and 2 meters in front of the eye.\"},{\"term\":\"Damage to the Visual System — UV at Altitude\",\"fact\":\"At altitude, light contains more of the high energy blue and ultraviolet wavelengths than is experienced at sea level.\"},{\"term\":\"VISUAL DEFECTS\",\"fact\":\"The most common visual defects are caused by the distorted shape of the eyeball.\"},{\"term\":\"MYOPIA (Short-sightedness)\",\"fact\":\"Myopia is more commonly known as short-sightedness.\"}],\"human-performance/hpl-13\":[{\"term\":\"Conductive Deafness\",\"fact\":\"Conductive Deafness — is caused by damage to the ossicles or the ear drum.\"},{\"term\":\"Presbycusis — Hearing loss with age\",\"fact\":\"Presbycusis — is the name given to the deterioration of hearing with advanced age.\"},{\"term\":\"The Ear and Balance · Orientation\",\"fact\":\"VISION is primary The primary and most reliable sense of spatial orientation is EYESIGHT.\"},{\"term\":\"OTOLITHS — linear acceleration\",\"fact\":\"The otoliths are tiny calcium-carbonate crystals embedded in a gelatinous membrane sitting on top of hair cells in the utricle and saccule.\"},{\"term\":\"How Angular Acceleration is Sensed — DGCA-quoted\",\"fact\":\"Fluid flow occurs when the body is subject to angular acceleration.\"}],\"human-performance/hpl-14\":[{\"term\":\"ILLUSIONS — Introduction\",\"fact\":\"In aviation any mismatch between what we sense and what we expect is an illusion.\"},{\"term\":\"Width & Slope of Runways\",\"fact\":\"A pilot used to a standard width runway may, when approaching an unfamiliar NARROW runway, judge he is too high and therefore round out too low on approach.\"},{\"term\":\"Maintenance of the Glide Slope\",\"fact\":\"Aiming Pilot & Aircraft Attitude Pitch Angle Once established on the glide path, it is relatively easy to visually maintain the glide path by keeping the aiming point at a FIXED POSITION on the windscreen.\"},{\"term\":\"PROTECTIVE MEASURES AGAINST ILLUSIONS\",\"fact\":\"The need for comprehensive flight briefing should the occurrence of illusions be known to exist or are anticipated at particular geographic locations.\"},{\"term\":\"Air / Motion Sickness\",\"fact\":\"Air/Motion Sickness — this mismatch between vestibular and visual sensory input is the PRIMARY CAUSE of spatial disorientation, and indeed of motion sickness.\"}],\"human-performance/hpl-16\":[{\"term\":\"PHYSICAL CHARACTERISTICS — Individual Differences\",\"fact\":\"Differences among individuals are remarkable.\"},{\"term\":\"Body Mass Index (BMI)\",\"fact\":\"A person's Body Mass Index, or BMI, is simply a measure of a person's weight in relation to his height.\"},{\"term\":\"Vitamins\",\"fact\":\"Vitamins are organic substances required by the body to function properly.\"},{\"term\":\"Minerals — the Three Majors\",\"fact\":\"Minerals are essential to many vital body processes — from building strong bones to transmitting nerve impulses.\"},{\"term\":\"Gastroenteritis — Pilot Fitness Rule\",\"fact\":\"Pilots suffering from Gastroenteritis are NOT FIT TO FLY, even though they may be taking medicine which is relieving the symptoms.\"}],\"human-performance/hpl-17\":[{\"term\":\"Sinus Blockage\",\"fact\":\"Slowing or stopping the descent until the pressure inside the sinus equalizes with the external pressure is the best course of action once this condition occurs.\"},{\"term\":\"Personal Hygiene\",\"fact\":\"A high standard of personal hygiene must be practiced if the body is to remain healthy and free from infection.\"}],\"human-performance/hpl-18\":[{\"term\":\"Four Reasons Medicines Have Flight-Qualification Consequences\",\"fact\":\"The effects of medicine do not necessarily immediately disappear when the treatment is stopped.\"},{\"term\":\"CAFFEINE\",\"fact\":\"Caffeine is present in coffee, tea, cocoa, chocolate, and fizzy drinks such as cola.\"}],\"human-performance/hpl-20\":[{\"term\":\"Receptors & Sensory Memories — Key Features\",\"fact\":\"The sensory stores for sight and sound are the most important, and knowledge of these is necessary.\"},{\"term\":\"Sensory Memory for Sight — Iconic Memory\",\"fact\":\"The Iconic Memory is the visual sensory store.\"},{\"term\":\"Perception\",\"fact\":\"The process of perception is greatly assisted by our ability to form mental and three-dimensional visual models.\"},{\"term\":\"Attention\",\"fact\":\"Attention is the process of directing and focusing psychological resources to enhance perception, performance and mental experience.\"},{\"term\":\"Types of Attention\",\"fact\":\"Selective Attention — inputs are sampled continually to decide their relevance to the present task at hand.\"}],\"human-performance/hpl-21\":[{\"term\":\"Surprise and Startle\",\"fact\":\"The startle reflex is a reflex-like event that blinks the eyes and causes a whole-body 'jerk' to occur (similar to that sometimes caused in sleep).\"},{\"term\":\"Limitations of Short-Term Memory\",\"fact\":\"The capacity of our short-term memory is limited.\"},{\"term\":\"The Learning Process\",\"fact\":\"Learning is an internal process which allows the mental acquisition and retention of data.\"},{\"term\":\"Motivation\",\"fact\":\"Motivation is the combination of a person's desire and energy directed at achieving a goal.\"},{\"term\":\"Response Times\",\"fact\":\"Response to reaction time is the interval between the onset of a given signal and the production of a response to that signal.\"}],\"human-performance/hpl-22\":[{\"term\":\"Judgment & Decision Making\",\"fact\":\"Making good decisions is one of the important aspects of piloting an aircraft.\"},{\"term\":\"Communication & Team Work\",\"fact\":\"Concise and unambiguous communication is essential to the safe conduct of air traffic.\"},{\"term\":\"Automation\",\"fact\":\"Automation refers to a system or method in which many of the processes of production are automatically performed or controlled by self-operating machines, electronic devices, etc.\"},{\"term\":\"Personality\",\"fact\":\"A low-neuroticism personality is one of an emotionally stable person, whereas a high-neuroticism person will worry and get upset easily.\"}],\"human-performance/hpl-23\":[{\"term\":\"Stress, Arousal and Performance\",\"fact\":\"The response of a person to the event or circumstances to which he is exposed is known as arousal.\"},{\"term\":\"Managing Stress\",\"fact\":\"Recognising stress, accepting it and developing a coping strategy is essential for stress management.\"},{\"term\":\"Tiredness and Fatigue\",\"fact\":\"Fatigue is a very deep tiredness due to the cumulative effects of a stressful lifestyle and/or living and working environment.\"},{\"term\":\"Arousal\",\"fact\":\"Arousal is a major aspect of many learning theories and is closely related to other concepts such as anxiety, attention, agitation, stress and motivation.\"}],\"human-performance/hpl-24\":[{\"term\":\"The Circadian Circle\",\"fact\":\"Human performance degradation at circadian lows is one of the major challenges for the aviation industry.\"},{\"term\":\"Melatonin — \\\"The Light of Night\\\"\",\"fact\":\"Melatonin is secreted from the pineal gland principally at night.\"},{\"term\":\"Sleep Inertia\",\"fact\":\"Refers to the transitional state between sleep and wake, marked by impaired performance, reduced vigilance, and a desire to return to sleep.\"}],\"guides/cpl-mock-tests\":[{\"term\":\"Strategies for Taking Mock Tests\",\"fact\":\"The most important part of a mock test is the review.\"}],\"guides/dgca-cpl-exam-pattern\":[{\"term\":\"The single biggest misunderstanding: the Navigation paper\",\"fact\":\"The Navigation paper is not one subject.\"}],\"guides/pilot-training-cost-india\":[{\"term\":\"The hourly rate — and what it includes\",\"fact\":\"The single most important question to ask a flying school, and the one prospective students most often forget: what exactly is in the hourly rate?\"}]}");
